const runtime = ($env.RUNTIME_INTERNAL_URL || '').replace(/\/$/, '');
const runtimeToken = ($env.RUNTIME_API_TOKEN || '').trim();
const botToken = ($env.TELEGRAM_BOT_TOKEN || '').trim();
const ownerUserId = ($env.TELEGRAM_OWNER_USER_ID || '').trim();
const ownerChatId = ($env.TELEGRAM_CHAT_ID || '').trim();
if (!runtime || !runtimeToken) throw new Error('Runtime control transport is not configured');
if (!botToken || !ownerUserId || !ownerChatId) return [{json:{status:'telegram_control_not_configured'}}];
const request = (options) => this.helpers.httpRequest({...options, json:true});
const state = $getWorkflowStaticData('global');
const offset = Number(state.telegram_update_offset || 0);
const updates = await request({
  method:'GET',
  url:`https://api.telegram.org/bot${botToken}/getUpdates`,
  qs:{offset, limit:20, timeout:0, allowed_updates:JSON.stringify(['callback_query'])},
});
if (!updates || updates.ok !== true || !Array.isArray(updates.result)) throw new Error('Telegram update polling failed');
const auth = {'Authorization': `Bearer ${runtimeToken}`, 'Content-Type':'application/json'};
let handled = 0;
for (const update of updates.result) {
  state.telegram_update_offset = Math.max(Number(state.telegram_update_offset || 0), Number(update.update_id || 0) + 1);
  const cb = update.callback_query;
  if (!cb) continue;
  const fromId = String((cb.from || {}).id || '');
  const chatId = String((((cb.message || {}).chat || {}).id) || '');
  const callbackId = String(cb.id || '');
  const data = String(cb.data || '');
  const answer = async (text, alert=false) => request({
    method:'POST',
    url:`https://api.telegram.org/bot${botToken}/answerCallbackQuery`,
    headers:{'Content-Type':'application/json'},
    body:{callback_query_id:callbackId, text:String(text).slice(0,180), show_alert:Boolean(alert)},
  });
  if (fromId !== ownerUserId || chatId !== ownerChatId) {
    await answer('Unauthorized owner control.', true);
    continue;
  }
  const match = data.match(/^act:([A-Za-z0-9_-]{8,60})$/);
  if (!match) {
    await answer('Invalid or stale action.', true);
    continue;
  }
  await answer('Đang xử lý action…');
  const actionId = match[1];
  try {
    const result = await request({
      method:'POST',
      url:`${runtime}/v1/control-actions/${encodeURIComponent(actionId)}/execute`,
      headers:auth,
      body:{telegram_user_id:fromId, telegram_chat_id:chatId},
    });
    const lines = ['🟢 Owner action processed', '', result.message || 'Runtime accepted the action.'];
    if (result.job_id) lines.push(`Job: ${String(result.job_id).slice(0,12)}…`);
    if (result.job_status) lines.push(`Status: ${result.job_status}`);
    const budget = result.budget_authorization || {};
    if (budget.dimension) lines.push(`Budget: ${budget.used} / ${budget.previous_limit} → ${budget.used} / ${budget.new_limit}`);
    const advisory = result.advisory || {};
    if (advisory.reason) lines.push('', `Reason: ${advisory.reason}`);
    if (advisory.cause) lines.push('', 'Why:', advisory.cause);
    if (advisory.recommended) lines.push('', 'Recommended:', advisory.recommended);
    await request({
      method:'POST',
      url:`https://api.telegram.org/bot${botToken}/sendMessage`,
      headers:{'Content-Type':'application/json'},
      body:{chat_id:ownerChatId, text:lines.join('\n').slice(0,3900), disable_web_page_preview:true},
    });
    handled += 1;
  } catch (error) {
    await request({
      method:'POST',
      url:`https://api.telegram.org/bot${botToken}/sendMessage`,
      headers:{'Content-Type':'application/json'},
      body:{
        chat_id:ownerChatId,
        text:'🔴 Owner action was rejected or failed safely. Runtime state was not force-advanced. Wait for the next actionable notification or inspect the dashboard/runtime status.',
      },
    });
  }
}
return [{json:{status:'ok', handled, next_offset:Number(state.telegram_update_offset || offset)}}];
